// Reads the settings from the "Set configuration" node.
const settings = $('Set configuration').first().json;
const allowTag = String(settings.allowTag || '').trim().toLowerCase();
const timedTypes = [
  'n8n-nodes-base.scheduleTrigger',
  'n8n-nodes-base.cron',
  'n8n-nodes-base.interval',
];

const result = [];
for (const item of $input.all()) {
  const wf = item.json;
  // Never touch this workflow itself.
  if (wf.id === $workflow.id) continue;

  const tags = (wf.tags || []).map((t) => String(t.name || '').toLowerCase());
  if (allowTag && tags.includes(allowTag)) continue;

  // Schedule triggers, plus any polling trigger (they all carry pollTimes).
  const timed = (wf.nodes || []).filter(
    (n) =>
      !n.disabled &&
      (timedTypes.includes(n.type) ||
        (settings.includePollingTriggers && n.parameters && n.parameters.pollTimes)),
  );
  if (timed.length === 0) continue;

  result.push({
    json: {
      id: wf.id,
      name: wf.name,
      triggers: timed.map((n) => n.name).join(', '),
    },
  });
}
return result;

const settings = $('Set configuration').first().json;
const found = $('Find timed workflows without the tag').all();
const lines = found.map((i) => `- ${i.json.name} (id ${i.json.id}; trigger: ${i.json.triggers})`);

const header = settings.dryRun
  ? `[${settings.instanceLabel}] Dry run. ${found.length} published workflow(s) run on a timer and have no "${settings.allowTag}" tag. They WOULD be unpublished:`
  : `[${settings.instanceLabel}] Unpublished ${found.length} workflow(s) that run on a timer and have no "${settings.allowTag}" tag:`;
const footer = settings.dryRun
  ? `Nothing was changed. To unpublish them for real, set dryRun to false in "Set configuration".`
  : `To keep a workflow running on this instance, add the "${settings.allowTag}" tag and publish it again.`;

return [{ json: { report: [header, ...lines, footer].join('\n'), count: found.length, dryRun: settings.dryRun } }];
